{"type":"table","attrs":{"isNumberColumnEnabled":false,"layout":"center","localId":"5a05c58d-fbd6-4aa6-a7be-a9f71ff0f9ec"},"content":[{"type":"tableRow","attrs":{"localId":"4d516400a523"},"content":[{"type":"tableCell","attrs":{"localId":"34f64c08607f"},"content":[{"type":"paragraph","content":[{"type":"text","text":"User Story","marks":[{"type":"strong"}]}],"attrs":{"localId":"28ea10c6a49b"}}]},{"type":"tableCell","attrs":{"localId":"9e8e99af3f8f"},"content":[{"type":"paragraph","content":[{"type":"text","text":"As a Technical Support Staff member, I want to check whether sufficient suitable equipment is available for an event's requested date and time, so that I can determine if the event's technical requirements can be fulfilled."}],"attrs":{"localId":"9766af886546"}}]}]},{"type":"tableRow","attrs":{"localId":"f81f881a4dcc"},"content":[{"type":"tableCell","attrs":{"localId":"48783f850be9","colspan":2},"content":[{"type":"paragraph","content":[{"type":"text","text":"Acceptance Criteria","marks":[{"type":"strong"}]}],"attrs":{"localId":"835bf353b115"}}]}]},{"type":"tableRow","attrs":{"localId":"0d5e17842dab"},"content":[{"type":"tableCell","attrs":{"localId":"4a7c81bece64","colspan":2},"content":[{"type":"paragraph","content":[{"type":"text","text":"Ensure that the Technical Support Staff member:"}],"attrs":{"localId":"32069359ce4c"}},{"type":"paragraph","attrs":{"localId":"ab97797ab868"}},{"type":"bulletList","content":[{"type":"listItem","attrs":{"localId":"5ef8835578e5"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Can view the requested equipment types, requested quantities, and the event date/time window."}],"attrs":{"localId":"8528f4fa385f"}}]}],"attrs":{"localId":"b8a5a12ded8b"}},{"type":"paragraph","attrs":{"localId":"311c4d88fc4f"}},{"type":"bulletList","content":[{"type":"listItem","attrs":{"localId":"09461c4d2bf4"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Is shown only equipment that excludes units marked as damaged, undergoing maintenance, or reserved for overlapping bookings."}],"attrs":{"localId":"9d5a23cf2d78"}}]}],"attrs":{"localId":"8fb9f53701ed"}},{"type":"paragraph","attrs":{"localId":"02613e04cfc5"}},{"type":"bulletList","content":[{"type":"listItem","attrs":{"localId":"e49a6fb158b3"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Can perform the availability check independently of whether the venue booking is confirmed."}],"attrs":{"localId":"c4a7eb94e6b6"}}]}],"attrs":{"localId":"a584a8ac3064"}},{"type":"paragraph","attrs":{"localId":"48955b8dff7d"}},{"type":"bulletList","content":[{"type":"listItem","attrs":{"localId":"f47da9809257"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Given an event request with equipment requirements, when the available quantity meets or exceeds the requested quantity for all items on that date/time, then the system marks the technical requirements as \"Fulfillable\" with a green confirmation indicator."}],"attrs":{"localId":"d119748e8249"}}]}],"attrs":{"localId":"d09181c08d1d"}},{"type":"paragraph","attrs":{"localId":"8404e0d2f7f1"}},{"type":"bulletList","content":[{"type":"listItem","attrs":{"localId":"33f8d1811162"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Given an event request with equipment requirements, when any requested item has fewer available units than requested, then the system marks the technical requirements as \"Shortfall / Unfulfillable\" and highlights the specific item deficit."}],"attrs":{"localId":"8beed0abe4bc"}}]}],"attrs":{"localId":"4cf528b3d959"}}]}]}]}
{adf}

{adf:display=block}
{"type":"table","attrs":{"isNumberColumnEnabled":false,"layout":"center","localId":"4290dad5-161d-4beb-ab5a-25755f354916"},"content":[{"type":"tableRow","attrs":{"localId":"b845b772d2c3"},"content":[{"type":"tableCell","attrs":{"localId":"44dc934eac85"},"content":[{"type":"paragraph","content":[{"type":"text","text":"User Story","marks":[{"type":"strong"}]}],"attrs":{"localId":"d142eb2034bb"}}]},{"type":"tableCell","attrs":{"localId":"de441080af41"},"content":[{"type":"paragraph","content":[{"type":"text","text":"As a Technical Support Staff member, I want to update the operational status of unavailable equipment so that damaged or maintained equipment is not incorrectly treated as available for event use. "}],"attrs":{"localId":"de73959c09d3"}}]}]},{"type":"tableRow","attrs":{"localId":"83dd47743fb8"},"content":[{"type":"tableCell","attrs":{"localId":"59553417be19","colspan":2},"content":[{"type":"paragraph","content":[{"type":"text","text":"Acceptance Criteria","marks":[{"type":"strong"}]}],"attrs":{"localId":"91e417aea241"}}]}]},{"type":"tableRow","attrs":{"localId":"8fcf6688c9f7"},"content":[{"type":"tableCell","attrs":{"localId":"7172daf4dec9","colspan":2},"content":[{"type":"bulletList","content":[{"type":"listItem","attrs":{"localId":"0a46fac438c7"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Technical Support Staff can view the current operational status of equipment."}],"attrs":{"localId":"e4f8fed7967c"}}]},{"type":"listItem","attrs":{"localId":"49185cd30cf7"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Technical Support Staff can mark equipment as unavailable when it is damaged, undergoing repair or maintenance, or otherwise unavailable for event use."}],"attrs":{"localId":"ef568dd07736"}}]},{"type":"listItem","attrs":{"localId":"0b7e57a94e79"},"content":[{"type":"paragraph","content":[{"type":"text","text":"When the equipment's operational status is changed, the updated status is saved."}],"attrs":{"localId":"cc868a5ca079"}}]},{"type":"listItem","attrs":{"localId":"48c97ee9dcb9"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Equipment marked as unavailable is not counted as available when equipment availability is checked for an event."}],"attrs":{"localId":"b3b804f2f2b1"}}]},{"type":"listItem","attrs":{"localId":"101dd4769024"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Equipment marked as unavailable cannot be newly reserved for an event while it remains unavailable."}],"attrs":{"localId":"f4ceac7947c3"}}]},{"type":"listItem","attrs":{"localId":"15d90df3db91"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Technical Support Staff can update the equipment's operational status when it becomes available for event use again."}],"attrs":{"localId":"3447ea5a1f53"}}]}],"attrs":{"localId":"b888e96922e6"}}]}]}]}
{adf}
